"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["22562"],{64(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>a,contentTitle:()=>s,toc:()=>l,assets:()=>h});var o=JSON.parse('{"id":"qiangguo/northkoreanproblem","title":"","description":"Recently, some people have again begun peddling the notion that we shouldn\'t waste our worry on North Korea, saying things like war won\'t break out and the probability is very small. Such people are either harboring ulterior motives or short-sighted.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/northkoreanproblem.md","sourceDirName":"qiangguo","slug":"/qiangguo/northkoreanproblem","permalink":"/en/qiangguo/northkoreanproblem","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"northkoreanproblem","title":"","hide_table_of_contents":true,"sidebar_label":"On the North Korea Issue, We Must Not Be Short-Sighted."},"sidebar":"qiangguoSidebar","previous":{"title":"The Great Significance of the Korean War Lies in It Being the Beginning of the Soviet Union\'s Failure and a Rehearsal for China\'s Rise","permalink":"/en/qiangguo/koreanwarsignificance"},"next":{"title":"\u8BA8\u8BBA\u4E4B\u4E8C\uFF1A\u53F0\u72EC\u7684\u6839\u6E90\u53CA\u6211\u4EEC\u7684\u5BF9\u7B56","permalink":"/en/qiangguo/taiwanindependence"}}'),i=n(74848),r=n(28453);let a={id:"northkoreanproblem",title:"",hide_table_of_contents:!0,sidebar_label:"On the North Korea Issue, We Must Not Be Short-Sighted."},s="On the North Korean Problem, One Must Not Be Short-Sighted",h={},l=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"on-the-north-korean-problem-one-must-not-be-short-sighted",children:"On the North Korean Problem, One Must Not Be Short-Sighted"})}),"\n",(0,i.jsx)(t.p,{children:"Recently, some people have again begun peddling the notion that we shouldn't waste our worry on North Korea, saying things like war won't break out and the probability is very small. Such people are either harboring ulterior motives or short-sighted."}),"\n",(0,i.jsx)(t.p,{children:"This young lady has already, in previous posts on the Korean issue, given a very clear characterization of the problem's significance for China: from an East Asian perspective, the Korean problem is a seven-party game (China, the US, Russia, Japan, North Korea, South Korea, and Taiwan). From a global strategic perspective, it is the key to a major transition between old and new world orders. East Asia, Eastern Europe, and Central Asia will be the positions where this transition is ultimately decided. From China's standpoint, there absolutely must be no missteps in East Asia. East Asian affairs should be led by East Asia, and ultimately by China -- this is the only direction for the problem's final resolution. Examining the Korean problem from this angle, the thinking becomes clear."}),"\n",(0,i.jsx)(t.p,{children:"Given this characterization, China should go all out to achieve leadership on the Korean problem, making comprehensive preparations. Every possible scenario should be considered with corresponding contingencies prepared. Whether war happens or not is not in itself the question -- it should be directed within China's overall East Asian strategic planning. Put bluntly, China should extract maximum national interest from leading on the Korean problem."}),"\n",(0,i.jsx)(t.p,{children:"So can China possibly take the lead on the Korean problem? Of course it can, and its position is the most favorable. Since this involves some sensitive matters, let me just illustrate by analogy. Anyone who has been in business knows the easiest way to gain dominance and maximum benefit: eating from both ends. Eating from both ends naturally requires skill, but this is precisely what makes business brilliant -- moreover, after eating from both ends, both sides still thank you. That is the highest of the high. From China's current position, China can absolutely not only eat from both ends on the Korean problem but eat all six other parties clean while leaving them unable to complain."}),"\n",(0,i.jsx)(t.p,{children:"In short, if you don't become the big brother, you'll inevitably end up the little brother. The Korean problem is an excellent opportunity for China to step onto the path of big brotherhood. If China doesn't seize it and put more effort into this problem, finding another opportunity later will be much harder."})]})}function d(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>s});var o=n(96540);let i={},r=o.createContext(i);function a(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);